vid(){ out=$1; img=$2; shift 2; u=$(higgsfield generate create kling3_0 --aspect_ratio 9:16 --duration 5 --sound off --start-image "$img" --prompt "$*" --wait --wait-timeout 25m 2>&1 | tail -1); curl -s -o "$out" "$u"; echo "$out $u"; }
S="Static fixed security camera, grainy night vision CCTV footage, no camera movement, cute absurd comedy, realistic physics."
vid EP06_opening.mp4 master.png "$S All the googly eyes on the rice containers suddenly jiggle and roll as if waking up, the containers wiggle slightly in place, then the ice cream tub's googly eyes turn to look at them." &
vid EP06_rollcall.mp4 master.png "$S Roll call: the rice containers hop up one after another in sequence from left to right like soldiers counting off, each landing back perfectly in line with a tiny puff of frost." &
vid EP06_stack.mp4 master.png "$S The rice containers hop and stack on top of each other one by one into a perfectly neat, tidy stacked tower, lids aligned, saving space, like a satisfying organizing video." &
vid EP06_block.mp4 master.png "$S The rice containers slide sideways in formation and line up as a wall directly in front of the ice cream tub, hiding it from view; the ice cream tub wobbles angrily and tries to peek over them." &
vid EP06_caught.mp4 master.png "$S Suddenly the freezer door is opened off-screen and bright warm kitchen light floods in, overexposing the image for a moment; every container and the ice cream tub instantly freezes completely motionless, comically stiff, googly eyes stop." &
vid EP06_hand.mp4 master.png "$S The freezer is lit by bright warm kitchen light. A human hand reaches into the freezer toward the ice cream tub, hesitates in mid-air, then changes direction and grabs one rice container instead and pulls it out of frame; the ice cream tub sags in disappointment, its googly eyes droop down." &
vid EP06_duru.mp4 duru.png "Static fixed security camera, grainy black and white night vision CCTV, no camera movement. The frozen toilet paper roll with googly eyes shivers violently, small ice pieces crack and fall off, its googly eyes wiggle, a little puff of frosty breath. Cute and funny." &
vid EP06_microwave.mp4 microwave.png "Static fixed home security camera, slight CCTV grain, no camera movement. Inside the running microwave the rice container with googly eyes slowly rotates on the turntable, steam rises from the hot rice, its googly eyes wiggle happily. Warm orange glow, cozy." &
